-- Exchange purposes (TEFCA XP codes such as T-TRTMNT) each subscriber organization is authorized to carry in its
-- certificates' SANs. Issuance and RA approval check SANs against this list, and withdrawing an exchange purpose
-- lets the RA revoke every certificate of the organization that carries it.

CREATE TABLE "OrganizationExchangePurposes" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "OrganizationId" INTEGER NOT NULL,
    "Code" CHARACTER VARYING(64) NOT NULL,
    "ApprovedBy" CHARACTER VARYING(256) NOT NULL,
    "ApprovedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT "PK_OrganizationExchangePurposes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_OrganizationExchangePurposes_Organizations_OrganizationId" FOREIGN KEY ("OrganizationId") REFERENCES "Organizations" ("Id") ON DELETE CASCADE
);

CREATE UNIQUE INDEX "IX_OrganizationExchangePurposes_OrganizationId_Code" ON "OrganizationExchangePurposes" USING btree ("OrganizationId", "Code");

COMMENT ON TABLE "OrganizationExchangePurposes" IS 'Exchange purposes a subscriber organization is authorized for; a withdrawn one is deleted and kept in the audit trail';

COMMENT ON COLUMN "OrganizationExchangePurposes"."Id" IS 'Primary key';

COMMENT ON COLUMN "OrganizationExchangePurposes"."OrganizationId" IS 'Subscriber organization (Organizations.Id)';

COMMENT ON COLUMN "OrganizationExchangePurposes"."Code" IS 'Exchange purpose code, upper-case, e.g. T-TRTMNT';

COMMENT ON COLUMN "OrganizationExchangePurposes"."ApprovedBy" IS 'RA or portal admin account that recorded the authorization';

COMMENT ON COLUMN "OrganizationExchangePurposes"."ApprovedAt" IS 'When the authorization was recorded (UTC)';
